import { MakeLogicType, actions, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { getCurrentTeamId } from 'lib/utils/getAppContext'

import {
    conversationsTicketsGithubLinksCreate,
    conversationsTicketsGithubLinksDestroy,
    conversationsTicketsGithubLinksRetrieve,
} from '../../generated/api'
import type { TicketGithubLinkApi } from '../../generated/api.schemas'

export interface GithubLinksLogicProps {
    ticketId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface githubLinksLogicValues {
    githubLinks: TicketGithubLinkApi[]
    githubLinksLoading: boolean
    linkSubmitting: boolean
    newLinkUrl: string
    removingLinkIds: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface githubLinksLogicActions {
    addGithubLink: () => {
        value: true
    }
    addGithubLinkFailure: () => {
        value: true
    }
    addGithubLinkSuccess: (
        link: TicketGithubLinkApi,
        alreadyLinked: boolean
    ) => {
        alreadyLinked: boolean
        link: TicketGithubLinkApi
    }
    loadGithubLinks: () => any
    loadGithubLinksFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGithubLinksSuccess: (
        githubLinks: TicketGithubLinkApi[],
        payload?: any
    ) => {
        githubLinks: TicketGithubLinkApi[]
        payload?: any
    }
    removeGithubLink: (linkId: string) => {
        linkId: string
    }
    removeGithubLinkFailure: (linkId: string) => {
        linkId: string
    }
    removeGithubLinkSuccess: (linkId: string) => {
        linkId: string
    }
    setNewLinkUrl: (url: string) => {
        url: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface githubLinksLogicMeta {
    key: string
}

export type githubLinksLogicType = MakeLogicType<
    githubLinksLogicValues,
    githubLinksLogicActions,
    GithubLinksLogicProps,
    githubLinksLogicMeta
>

export const githubLinksLogic = kea<githubLinksLogicType>([
    props({} as GithubLinksLogicProps),
    key((props) => props.ticketId),
    path((key) => ['products', 'conversations', 'scenes', 'ticket', 'githubLinksLogic', key]),
    actions({
        setNewLinkUrl: (url: string) => ({ url }),
        addGithubLink: true,
        addGithubLinkSuccess: (link: TicketGithubLinkApi, alreadyLinked: boolean) => ({ link, alreadyLinked }),
        addGithubLinkFailure: true,
        removeGithubLink: (linkId: string) => ({ linkId }),
        removeGithubLinkSuccess: (linkId: string) => ({ linkId }),
        removeGithubLinkFailure: (linkId: string) => ({ linkId }),
    }),
    loaders(({ props }) => ({
        githubLinks: [
            [] as TicketGithubLinkApi[],
            {
                loadGithubLinks: async () =>
                    await conversationsTicketsGithubLinksRetrieve(String(getCurrentTeamId()), props.ticketId),
            },
        ],
    })),
    reducers({
        githubLinks: {
            addGithubLinkSuccess: (state, { link, alreadyLinked }) => (alreadyLinked ? state : [...state, link]),
            removeGithubLinkSuccess: (state, { linkId }) => state.filter((link) => link.id !== linkId),
        },
        newLinkUrl: [
            '',
            {
                setNewLinkUrl: (_, { url }) => url,
                addGithubLinkSuccess: () => '',
            },
        ],
        linkSubmitting: [
            false,
            {
                addGithubLink: () => true,
                addGithubLinkSuccess: () => false,
                addGithubLinkFailure: () => false,
            },
        ],
        removingLinkIds: [
            [] as string[],
            {
                removeGithubLink: (state, { linkId }) => (state.includes(linkId) ? state : [...state, linkId]),
                removeGithubLinkSuccess: (state, { linkId }) => state.filter((id) => id !== linkId),
                removeGithubLinkFailure: (state, { linkId }) => state.filter((id) => id !== linkId),
            },
        ],
    }),
    listeners(({ actions, values, props }) => ({
        addGithubLink: async () => {
            const url = values.newLinkUrl.trim()
            if (!url) {
                actions.addGithubLinkFailure()
                return
            }
            try {
                const link = await conversationsTicketsGithubLinksCreate(String(getCurrentTeamId()), props.ticketId, {
                    url,
                })
                const alreadyLinked = values.githubLinks.some((existing) => existing.id === link.id)
                actions.addGithubLinkSuccess(link, alreadyLinked)
                if (alreadyLinked) {
                    lemonToast.info(`${link.repo}#${link.number} is already linked to this ticket`)
                }
            } catch (error: any) {
                actions.addGithubLinkFailure()
                lemonToast.error(error?.detail || "Couldn't link that issue or PR. Check the reference and try again.")
            }
        },
        removeGithubLink: async ({ linkId }) => {
            try {
                await conversationsTicketsGithubLinksDestroy(String(getCurrentTeamId()), props.ticketId, linkId)
                actions.removeGithubLinkSuccess(linkId)
            } catch {
                actions.removeGithubLinkFailure(linkId)
                lemonToast.error('Failed to remove the GitHub link')
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadGithubLinks()
    }),
])
